'use client';

import * as React from 'react';
import { Phone } from 'lucide-react';
import type { FlagProps } from 'react-phone-number-input';
import flags from 'react-phone-number-input/flags';

export function CheckoutPhoneFlag({
  country,
  countryName,
  fallback,
}: FlagProps & { fallback?: React.ReactNode }) {
  const mounted = React.useSyncExternalStore(
    () => () => {},
    () => true,
    () => false,
  );
  const Flag = flags[country];

  return (
    <span
      className="checkout-phone-flag inline-flex h-5 w-5 shrink-0 overflow-hidden rounded-sm"
      suppressHydrationWarning
    >
      {mounted && Flag ? (
        <Flag title={countryName} />
      ) : (
        (fallback ?? <Phone size={16} aria-hidden="true" role="presentation" />)
      )}
    </span>
  );
}

'use client';

import * as React from 'react';
import { ChevronDown } from 'lucide-react';
import * as RPNInput from 'react-phone-number-input';
import type { FlagProps } from 'react-phone-number-input';
import { CheckoutPhoneFlag } from './checkout-phone-flag';

const INPUT_BORDER = 'clamp(1px, 0.12vw, 1.3px) solid #d1d5db';

export type CheckoutCountrySelectProps = {
  disabled?: boolean;
  value: RPNInput.Country;
  onChange: (value: RPNInput.Country) => void;
  options: { label: string; value: RPNInput.Country }[];
  flagComponent?: React.ComponentType<FlagProps>;
};

/** Mirrors apps/checkout phone-number-input CountrySelect. */
export function CheckoutCountrySelect({
  disabled,
  value,
  onChange,
  options,
  flagComponent: FlagComponent = CheckoutPhoneFlag,
}: CheckoutCountrySelectProps) {
  return (
    <div
      className="relative inline-flex items-center self-stretch bg-transparent h-10 pe-2 ps-3 text-foreground transition-colors border-0 shadow-none rounded-l-sm"
      style={{ borderRight: INPUT_BORDER }}
    >
      <div className="inline-flex items-center gap-1" aria-hidden="true">
        <FlagComponent country={value} countryName={value} aria-hidden="true" />
        <span className="text-muted-foreground/80">
          <ChevronDown size={16} strokeWidth={2} aria-hidden="true" />
        </span>
      </div>
      <select
        disabled={disabled}
        value={value || ''}
        onChange={(event) => onChange(event.target.value as RPNInput.Country)}
        className="absolute inset-0 text-sm opacity-0"
        aria-label="Select country"
        data-lpignore="true"
      >
        <option value="" className="text-gray-400">
          Select country
        </option>
        {options
          .filter((option) => option.value)
          .map((option) => (
            <option key={option.value || 'empty'} value={option.value}>
              {option.label}{' '}
              {option.value &&
                `+${RPNInput.getCountryCallingCode(option.value)}`}
            </option>
          ))}
      </select>
    </div>
  );
}

'use client';

import * as React from 'react';
import * as RPNInput from 'react-phone-number-input';
import { isValidPhoneNumber } from 'react-phone-number-input';
import { CheckoutInput } from './checkout-input';
import { CheckoutCountrySelect } from './checkout-country-select';
import { CheckoutPhoneFlag } from './checkout-phone-flag';

export interface CheckoutPhoneNumberInputProps {
  value: string;
  onChange: (value: string | undefined) => void;
  onCountryChange?: (country: string) => void;
  onValidationChange?: (isValid: boolean | undefined) => void;
  defaultCountry?: RPNInput.Country;
}

export function CheckoutPhoneNumberInput({
  value,
  onChange,
  onCountryChange,
  onValidationChange,
  defaultCountry,
}: CheckoutPhoneNumberInputProps) {
  const debounceRef = React.useRef<ReturnType<typeof setTimeout>>(undefined);
  const hasTouchedRef = React.useRef(false);

  const markTouched = React.useCallback(() => {
    hasTouchedRef.current = true;
  }, []);

  const validatePhoneNumber = React.useCallback(
    (phoneValue: string) => {
      if (phoneValue && phoneValue.trim().length >= 7) {
        onValidationChange?.(isValidPhoneNumber(phoneValue));
      } else if (phoneValue && phoneValue.trim().length > 0) {
        onValidationChange?.(undefined);
      } else {
        onValidationChange?.(undefined);
      }
    },
    [onValidationChange],
  );

  React.useEffect(() => {
    if (debounceRef.current) {
      clearTimeout(debounceRef.current);
    }

    debounceRef.current = setTimeout(() => {
      const hasMeaningfulValue = Boolean(value && value.trim().length >= 7);
      if (hasTouchedRef.current || hasMeaningfulValue) {
        validatePhoneNumber(value);
      }
    }, 500);

    return () => {
      if (debounceRef.current) {
        clearTimeout(debounceRef.current);
      }
    };
  }, [value, validatePhoneNumber]);

  return (
    <div className="space-y-2">
      <div className="relative shadow-sm shadow-black/[.04]">
        <div className="flex w-full rounded-none bg-transparent checkout-phone-shell">
          <RPNInput.default
            className="flex w-full"
            international
            defaultCountry={defaultCountry}
            flagComponent={CheckoutPhoneFlag}
            countrySelectComponent={CheckoutCountrySelect}
            inputComponent={PhoneInput}
            placeholder="Phone number"
            value={value}
            onChange={(next) => {
              markTouched();
              onChange(next);
            }}
            onCountryChange={(countryCode) => {
              if (countryCode) {
                markTouched();
                onCountryChange?.(countryCode);
              }
            }}
            onBlur={() => {
              markTouched();
              validatePhoneNumber(value);
            }}
            countryCallingCodeEditable
          />
        </div>
        <span className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-red-500">
          *
        </span>
      </div>
    </div>
  );
}

type InputProps = React.InputHTMLAttributes<HTMLInputElement>;

const PhoneInput = React.forwardRef<HTMLInputElement, InputProps>(
  ({ ...props }, ref) => (
    <CheckoutInput
      className="rounded-none border-0 bg-transparent focus-visible:ring-0"
      ref={ref}
      {...props}
      autoComplete="tel"
      data-lpignore="true"
      data-form-type="other"
    />
  ),
);
PhoneInput.displayName = 'PhoneInput';

