/* Hosted checkout parity — mirrors apps/checkout hosted/checkout.css */

.lomi-checkout-ui {
  color-scheme: light;
  --border: oklch(0.929 0.013 255.508);
  --card: oklch(1 0 0);
  --input-border: clamp(1px, 0.12vw, 1.3px) solid #d1d5db;
}

.lomi-checkout-ui .border.bg-card {
  background-color: white !important;
}

/* Override docs .prose img rules (aspect-ratio 16/9, object-fit cover) */
.lomi-checkout-ui img {
  margin: 0 !important;
  max-width: none !important;
  aspect-ratio: auto !important;
  box-shadow: none !important;
}

.lomi-checkout-ui .border.bg-card img {
  display: block;
  object-fit: contain;
}

/*
 * Stacked customer form — mirrors checkout form [&_*]:!rounded-none
 * then checkout.css re-applies corners on first/last rows only.
 */
.lomi-checkout-ui .customer-information-stack * {
  border-radius: 0 !important;
}

.lomi-checkout-ui input[name='fullName'].rounded-tl.rounded-tr,
.lomi-checkout-ui input.rounded-tl.rounded-tr {
  border-top-left-radius: 0.25rem !important;
  border-top-right-radius: 0.25rem !important;
  border-bottom-left-radius: 0 !important;
  border-bottom-right-radius: 0 !important;
}

.lomi-checkout-ui
  .customer-information-stack
  .w-full.rounded-none.box-border.bg-white {
  border-bottom-left-radius: 0.25rem !important;
  border-bottom-right-radius: 0.25rem !important;
}

.lomi-checkout-ui
  .customer-information-stack
  .whatsapp-input-container
  .flex.w-full.rounded-none {
  border-bottom-left-radius: 0.25rem !important;
  border-bottom-right-radius: 0.25rem !important;
}

/* Text/email fields — full border; exclude phone tel inputs */
.lomi-checkout-ui .customer-information-section input:not(.PhoneInputInput),
.lomi-checkout-ui .customer-information-section select {
  border-color: #d1d5db !important;
  border-style: solid !important;
  border-width: clamp(1px, 0.12vw, 1.3px) !important;
  outline: none !important;
  box-shadow: none !important;
}

.lomi-checkout-ui
  .customer-information-section
  input:not(.PhoneInputInput):focus,
.lomi-checkout-ui
  .customer-information-section
  input:not(.PhoneInputInput):focus-visible,
.lomi-checkout-ui
  .customer-information-section
  input:not(.PhoneInputInput):hover:focus,
.lomi-checkout-ui
  .customer-information-section
  input:not(.PhoneInputInput):active:focus,
.lomi-checkout-ui .customer-information-section select:focus,
.lomi-checkout-ui .customer-information-section select:focus-visible {
  border-color: #d1d5db !important;
  outline: none !important;
  box-shadow: none !important;
}

/* Phone / WhatsApp rows — full border like email, stacked with -mt-px */
.lomi-checkout-ui .customer-information-section .checkout-phone-shell {
  border: var(--input-border) !important;
  border-radius: 0 !important;
  background-color: white !important;
}

.lomi-checkout-ui .whatsapp-input-container * {
  box-sizing: border-box;
}

.lomi-checkout-ui .customer-information-stack .checkout-phone-flag,
.lomi-checkout-ui .customer-information-stack .checkout-phone-flag svg {
  border-radius: 0.25rem !important;
}

/* Phone input — mirrors checkout.css PhoneInput overrides */
.lomi-checkout-ui .PhoneInput,
.lomi-checkout-ui .PhoneInput *,
.lomi-checkout-ui .PhoneInputCountry,
.lomi-checkout-ui .PhoneInputInput {
  outline: none !important;
  box-shadow: none !important;
  border: none !important;
  background-color: transparent !important;
}

.lomi-checkout-ui .PhoneInput .relative.inline-flex.items-center.self-stretch,
.lomi-checkout-ui .relative.inline-flex.items-center.self-stretch {
  border-right: var(--input-border) !important;
}

.lomi-checkout-ui .PhoneInputInput,
.lomi-checkout-ui .whatsapp-input-container .PhoneInputInput {
  font-size: 0.875rem !important;
  line-height: 1.25rem !important;
  padding: 0.5rem 0.75rem !important;
}

.lomi-checkout-ui .customer-information-section .PhoneInputInput {
  padding-right: 1.5rem !important;
}

.lomi-checkout-ui .whatsapp-input-container input {
  padding-right: 2.5rem !important;
}

.lomi-checkout-ui .PhoneInputInput::placeholder,
.lomi-checkout-ui .whatsapp-input-container .PhoneInputInput::placeholder {
  font-size: 0.875rem !important;
  line-height: 1.25rem !important;
  color: #9ca3af !important;
}

/* Country flag — w-5 (20px) with rounded-sm */
.lomi-checkout-ui .checkout-phone-flag {
  width: 1.25rem !important;
  height: 1.25rem !important;
  min-width: 1.25rem;
  min-height: 1.25rem;
  overflow: hidden;
  border-radius: 0.25rem !important;
}

.lomi-checkout-ui .checkout-phone-flag svg {
  width: 1.25rem !important;
  height: 1.25rem !important;
  display: block;
  border-radius: 0.25rem !important;
}

.lomi-checkout-ui .PhoneInput select[aria-label='Select country'],
.lomi-checkout-ui
  .whatsapp-input-container
  select[aria-label='Select country'] {
  border: none !important;
}

/* SPI alias inputs outside customer stack */
.lomi-checkout-ui input[type='text']:not(.PhoneInputInput),
.lomi-checkout-ui input[type='email']:not(.PhoneInputInput) {
  border-color: #d1d5db !important;
  border-style: solid !important;
  border-width: clamp(1px, 0.12vw, 1.3px) !important;
  outline: none !important;
  box-shadow: none !important;
}

'use client';

import * as React from 'react';
import { LomiUiPreview } from '@/components/preview/lomi-ui-preview';
import { CustomerInformationSection } from '@/components/lomi-ui/customer-information-section';

export function CustomerInformationSectionDemo() {
  const [fullName, setFullName] = React.useState('');
  const [email, setEmail] = React.useState('');
  const [phoneNumber, setPhoneNumber] = React.useState('');
  const [whatsappNumber, setWhatsAppNumber] = React.useState('');
  const [isDifferentWhatsApp, setIsDifferentWhatsApp] = React.useState(false);

  return (
    <LomiUiPreview variant="checkout" innerClassName="flex justify-center">
      <CustomerInformationSection
        className="w-full max-w-sm"
        defaultCountry="CI"
        fullName={fullName}
        email={email}
        phoneNumber={phoneNumber}
        whatsappNumber={whatsappNumber}
        isDifferentWhatsApp={isDifferentWhatsApp}
        onFullNameChange={setFullName}
        onEmailChange={setEmail}
        onPhoneNumberChange={(value) => setPhoneNumber(value ?? '')}
        onWhatsAppNumberChange={(value) => setWhatsAppNumber(value ?? '')}
        onDifferentWhatsAppChange={setIsDifferentWhatsApp}
      />
    </LomiUiPreview>
  );
}
